wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, Intent, LlmError};

struct Node;

/// Precondition from the contract: `requires len(question) <= 512`.
const MAX_QUESTION_BYTES: usize = 512;

/// Bound on the tool-orchestration loop so a model that keeps asking for
/// tools can never spin forever.
const MAX_ROUNDS: usize = 8;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_system(ctx: &ConversationContext) -> String {
    let mut system = String::new();
    system.push_str(
        "You are a customer-support agent. Answer the user's question using only \
         the knowledge provided and the `lookup` tool. Classified intent: ",
    );
    system.push_str(intent_label(ctx.intent));
    system.push('.');

    if ctx.knowledge.is_empty() {
        system.push_str(" No pre-fetched knowledge was supplied.");
    } else {
        system.push_str(" Pre-fetched knowledge:");
        for (i, k) in ctx.knowledge.iter().enumerate() {
            system.push_str("\n- [");
            system.push_str(&i.to_string());
            system.push_str("] ");
            system.push_str(k);
        }
    }
    system
}

fn format_tool_result(tool: &str, query: &str, results: &[String]) -> String {
    let mut out = String::new();
    out.push_str("Tool `");
    out.push_str(tool);
    out.push_str("` for query ");
    out.push_str(query);
    out.push_str(" returned:");
    if results.is_empty() {
        out.push_str("\n(no results)");
    } else {
        for r in results {
            out.push_str("\n- ");
            out.push_str(r);
        }
    }
    out.push_str("\nUse this to answer the user's question.");
    out
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The contract guarantees `len(question) <= 512`; check defensively
        // and refuse rather than act on an input that violates the precondition.
        if ctx.question.len() > MAX_QUESTION_BYTES {
            return ResponseResult::Error(LlmError {
                message: "question exceeds the 512-byte bound".to_string(),
            });
        }

        let system = build_system(&ctx);
        let mut prompt = ctx.question.clone();

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // The only tool in this node's scope is `lookup`, backed by
                    // the read-only knowledge-base handle. Any other tool name
                    // is out of scope: report it as an empty result and let the
                    // model proceed without it, rather than inventing authority.
                    let results = if req.tool == "lookup" {
                        kb_read::lookup(&req.query)
                    } else {
                        Vec::new()
                    };
                    prompt = format_tool_result(&req.tool, &req.query, &results);
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the round limit"
                .to_string(),
        })
    }
}

export!(Node);
```

